INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (5063, 'Ngày hội văn hóa chợ nổi Cái Răng 2019 | Thời Gian | Địa Điểm | Cách đi', 'ngay-hoi-van-hoa-cho-noi-cai-rang-2019', '
<p>Ngày hội văn hóa chợ nổi Cái Răng 2019 diễn ra trong 3 ngày là 6/7 đến ngày 8/7/2019. Bạn sẽ được tham gia hoạt động vui chơi giải trí thú vị ở chợ nổi Cái Răng với nhiều chương trình độc đáo. Diễu hành ghe thuyền, trang trí ghe thuyền mới lạ, tham gia buffet ẩm thực bánh trái đặc sản miền Tây, khám phá đua ghe thuyền máy độc đáo trên sông chợ nổi Cái Răng,&#8230;</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1280" height="720" src="https://media.huynhhieutravel.com/giới-thiệu-ngày-hội-văn-hóa-chợ-nổi-cái-răng-1280x720.jpg" alt="Giơí thiệu lễ hội chợ nổi Cái Răng 2019" class="wp-image-5078" srcset="https://media.huynhhieutravel.com/giới-thiệu-ngày-hội-văn-hóa-chợ-nổi-cái-răng.jpg 1280w, https://media.huynhhieutravel.com/giới-thiệu-ngày-hội-văn-hóa-chợ-nổi-cái-răng-768x432.jpg 768w, https://media.huynhhieutravel.com/giới-thiệu-ngày-hội-văn-hóa-chợ-nổi-cái-răng-696x392.jpg 696w, https://media.huynhhieutravel.com/giới-thiệu-ngày-hội-văn-hóa-chợ-nổi-cái-răng-1068x601.jpg 1068w, https://media.huynhhieutravel.com/giới-thiệu-ngày-hội-văn-hóa-chợ-nổi-cái-răng-747x420.jpg 747w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Giơí thiệu lễ hội chợ nổi Cái Răng 2019</figcaption></figure>



<h2 class="wp-block-heading">Ngày hội văn hóa chợ nổi Cái Răng có gì</h2>



<p>Lễ hội chợ nổi Cái Răng là hoạt động thường niên diễn ra hàng năm. Nhiều chương trình xúc tiến du lịch được diễn ra song song cùng nhiều hoạt động vui chơi giải trí khác nhau. Bạn sẽ được tìm hiểu chi tiết nét văn hóa sông nước miền Nam qua các hoạt động diễu hành ghe thuyền, triễn lãm sách ảnh.</p>



<p>Đặc biệt những chương trình hấp dẫn như BUFFET trái cây, bánh trái dân gian miền Nam. Đây là những tiết mục cho du khách tận hưởng những loại đặc sản tươi ngon và ăn no &#8220;không đường về&#8221; của ngày hội.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/thuyết-minh-chợ-nổi-cái-răng-1024x682.jpg" alt="Thuyết minh chợ nổi Cái Răng" class="wp-image-3633" srcset="https://media.huynhhieutravel.com/thuyết-minh-chợ-nổi-cái-răng.jpg 1024w, https://media.huynhhieutravel.com/thuyết-minh-chợ-nổi-cái-răng-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Thuyết minh chợ nổi Cái Răng</figcaption></figure>



<p>Thêm vào đó những ghe thuyền trang trí, khung cảnh tấp nập được tái hiện càng khiến chợ nổi Cái Răng thêm hấp dẫn hơn. Bạn chắc chắn sẽ có một ngày vui chơi hấp dẫn đầy lý thú trên chợ nổi Cái Răng trong 3 ngày 6/7 đến ngày 8/7/2019.</p>



<figure><iframe width="560" height="315" src="https://www.youtube.com/embed/4lV9iocNrv0" allowfullscreen=""></iframe></figure>



<h2 class="wp-block-heading">Thời gian diễn ra ngày hội văn hóa chợ nổi Cái Răng</h2>



<p>Lịch trình diễn ra ngày hội văn hóa chợ nổi Cái Răng trong 3 ngày: Từ ngày 6 tháng 7 đến ngày 7 tháng 7 năm 2019. Sau đây là nội dung lịch trình.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="900" src="https://media.huynhhieutravel.com/Chợ-Nổi-Cái-Răng7-1024x900.jpg" alt="Đời sống ghe thuyền miền Tây" class="wp-image-1035"/><figcaption>Chợ Nổi Cái Răng &#8211; Huynh Hieu Travel</figcaption></figure>



<p>Các chương trình chính bao gồm:</p>



<ul class="wp-block-list"><li>Lễ khai mạc ngày 6 tháng 7.</li><li>Diễu hành ghe thuyền trên sông</li><li>Triển lãm sách và đố vui.</li><li>Triễn lãm ảnh và thư pháp về văn hóa chợ nổi Cái Răng và miền Tây sông nước.</li><li>Quảng bá và xúc tiến du lịch. Giao lưu du lịch giữa các công ty du lịch Cần Thơ và khách du lịch.</li><li>Tổ chức giải vô địch karate toàn miền Nam năm 2019.</li><li>Trưng bày và tọa hình nông sản từ các loại trái cây, lúa gạo,&#8230;</li><li>Giới thiệu những nông sản, trái cây miền Tây đến du khách.</li><li>Tổ chức trò chơi dân gian.</li><li>Tổ chức gian hàng ẩm thực với buffet bánh và trái cây.</li><li>Khuyến mãi giảm giá vé du lịch cho khách tham quan.</li><li>Tổ chức văn nghệ đờn ca tài tử nam bộ và hát dân ca.</li><li>Tổ chức bế mạc vào tối ngày 8/7/2019.</li></ul>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1280" height="720" src="https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-6-tháng-7-1280x720.jpg" alt="Lịch trình ngày hội văn hóa chợ nổi Cái Răng ngày 6 tháng 7" class="wp-image-5075" srcset="https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-6-tháng-7.jpg 1280w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-6-tháng-7-768x432.jpg 768w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-6-tháng-7-696x392.jpg 696w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-6-tháng-7-1068x601.jpg 1068w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-6-tháng-7-747x420.jpg 747w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Lịch trình ngày hội văn hóa chợ nổi Cái Răng ngày 6 tháng 7</figcaption></figure>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1280" height="720" src="https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-7-tháng-7-1280x720.jpg" alt="Lịch trình ngày hội văn hóa chợ nổi Cái Răng ngày 7 tháng 7" class="wp-image-5076" srcset="https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-7-tháng-7.jpg 1280w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-7-tháng-7-768x432.jpg 768w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-7-tháng-7-696x392.jpg 696w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-7-tháng-7-1068x601.jpg 1068w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-7-tháng-7-747x420.jpg 747w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Lịch trình ngày hội văn hóa chợ nổi Cái Răng ngày 7 tháng 7</figcaption></figure>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1280" height="720" src="https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-8-tháng-7-1280x720.jpg" alt="Lịch trình ngày hội văn hóa chợ nổi Cái Răng ngày 8 tháng 7" class="wp-image-5077" srcset="https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-8-tháng-7.jpg 1280w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-8-tháng-7-768x432.jpg 768w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-8-tháng-7-696x392.jpg 696w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-8-tháng-7-1068x601.jpg 1068w, https://media.huynhhieutravel.com/lịch-trình-ngày-hội-văn-hóa-chợ-nổi-cái-răng-8-tháng-7-747x420.jpg 747w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Lịch trình ngày hội văn hóa chợ nổi Cái Răng ngày 8 tháng 7</figcaption></figure>



<h2 class="wp-block-heading">Địa điểm diễn ra lễ hội chợ nổi Cái Răng</h2>



<p>Địa điểm gồm 2 nơi chính tổ chức là <a rel="noreferrer noopener" aria-label="Chợ nổi Cái Răng (mở trong tab mới)" href="https://goo.gl/maps/WefpT7ykfmkqM9b19" target="_blank">Chợ nổi Cái Răng</a> và <a rel="noreferrer noopener" aria-label="Trung tâm du lịch quận Cái Răng (mở trong tab mới)" href="https://goo.gl/maps/uho6oJ7zUUxsr83A9" target="_blank">Trung tâm du lịch quận Cái Răng</a>. Các bạn sẽ được tham quan diễu hành ghe thuyền, tham gia các hoạt động mua sắm, xem đua ghe thuyền tại chợ nổi Cái Răng. Ngoài ra tham gia gian hàng ẩm thực, các trò chơi dân gian và xem trưng bày nông sản và buffet bánh trái tại Trung tâm du lịch quận Cái Răng (Nằm gần ven bờ Chợ nổi Cái Răng).</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="900" src="https://media.huynhhieutravel.com/Chợ-Nổi-Cái-Răng4-1024x900.jpg" alt="Hàng nước di động" class="wp-image-1032"/><figcaption>Chợ Nổi Cái Răng &#8211; Huynh Hieu Travel</figcaption></figure>



<p><strong>Địa chỉ chợ nổi Cái Răng</strong></p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3929.1533992686705!2d105.74334461479422!3d10.004184992848327!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31a089afb6342d8d%3A0xcdb2b569f5f13898!2zQ2jhu6MgbuG7lWkgQ8OhaSBSxINuZw!5e0!3m2!1svi!2s!4v1562039651965!5m2!1svi!2s" width="600" height="450" allowfullscreen=""></iframe></figure>



<p><strong>Địa chỉ trung tâm du lịch quận Cái Răng</strong>: Võ Tánh, Lê Bình, Cái Răng, Cần Thơ, Việt Nam.</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3929.155824916616!2d105.74916551428201!3d10.003984475711738!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31a089b0de749db1%3A0x15f124621a8102e2!2zVHJ1bmcgVMOibSBEdSBM4buLY2ggUXXhuq1uIEPDoWkgUsSDbmc!5e0!3m2!1svi!2s!4v1562039701691!5m2!1svi!2s" width="600" height="450" allowfullscreen=""></iframe></figure>



<h2 class="wp-block-heading">Cách tham gia lễ hội chợ nổi Cái Răng</h2>



<p>Cách đơn giản nhất để tham gia lễ hội chợ nổi Cái Răng là thuê tour chợ nổi Cái Răng đi một trong 3 ngày 6/7 đến 8/7/2019. Bạn có thể tham khảo <a rel="noreferrer noopener" aria-label="Tour chợ nổi Cái Răng (mở trong tab mới)" href="https://nucuoimekong.com/tour/tour-cho-noi-cai-rang-miet-vuon/" target="_blank">Tour chợ nổi Cái Răng</a>. Tour trọn gói bao gồm tham quan chợ nổi Cái Răng &#8211; Miệt Vườn 3 cống &#8211; Lò hủ tiếu &#8211; Rạch Nhỏ.</p>



<p>Ngoài ra bạn có thể thuê ghe thuyền riêng vào ngày đó để có thể dừng chân mua sắm và vui chơi nhiều hơn. Số hotline đặt tàu ghe đi chợ nổi Cái Răng: 0939729609.</p>



<p>Tham khảo thêm <a rel="noreferrer noopener" aria-label="Kinh nghiệm đi chợ nổi Cái Răng (mở trong tab mới)" href="https://huynhhieutravel.com/cach-di-cho-noi-cai-rang/" target="_blank">Kinh nghiệm đi chợ nổi Cái Răng</a> dành cho những ai đi lần đầu.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="787" height="214" src="https://media.huynhhieutravel.com/Bảng-giá-thuê-tàu-chợ-nổi-cái-răng.png" alt="Bảng giá cho thuê tàu đi Chợ Nổi Cái Răng" class="wp-image-1967" srcset="https://media.huynhhieutravel.com/Bảng-giá-thuê-tàu-chợ-nổi-cái-răng.png 787w, https://media.huynhhieutravel.com/Bảng-giá-thuê-tàu-chợ-nổi-cái-răng-768x209.png 768w" sizes="(max-width: 787px) 100vw, 787px" /><figcaption>Bảng giá cho thuê tàu đi Chợ Nổi Cái Răng</figcaption></figure>



<h2 class="wp-block-heading">Nguồn gốc ngày hội văn hóa chợ nổi Cái Răng</h2>



<p>Nguồn gốc lễ hội chợ nổi Cái Răng có từ năm 2015 đến nay. Mỗi năm nó lại tổ chức 1 lần để hưởng ứng ngày hội du lịch Việt Nam vào đầu tháng 7 hàng năm. Ngoài ra nó còn tổ chức để tôn vinh, gìn giữ bản sắc chợ nổi Cái Răng.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="900" src="https://media.huynhhieutravel.com/Chợ-Nổi-Cái-Răng2-1024x900.jpg" alt="Tàu chở bí" class="wp-image-1030"/><figcaption>Chợ Nổi Cái Răng &#8211; Huynh Hieu Travel</figcaption></figure>



<p>Một hình thức quảng bá du lịch chợ nổi Cái Răng cũng như miền Tây nói chung. Tìm về những hoạt động văn hóa dân dã như đua xuồng ghe, tổ chức hội thi đờn ca tài tử, diễu hành ghe tại chợ nổi Cái Răng. Cũng như thu hút khách du lịch bằng các chương trình khuyến mãi giảm giá tour dành cho khách tham quan.</p>



<p>Hãy cùng tham gia lễ hội chợ nổi Cái Răng 2019 và chụp những bức hình đẹp, tham gia ăn uống thỏa thích trái cây và bánh dân gian bạn nhé!</p>
', 'Ngày hội văn hóa chợ nổi Cái Răng 2019 diễn ra trong 3 ngày là 6/7 đến ngày 8/7/2019. Bạn sẽ được tham gia hoạt động vui chơi giải trí thú vị ở chợ nổi Cái Răng với nhiều chương trình độc đáo. Diễu hành ghe thuyền, trang trí ghe thuyền mới lạ, tham gia [&hellip;]', 1035, 'post', '2019-07-02 04:21:45', '2023-04-23 12:47:30');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (5063, 34);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (5031, 'Tổng Hợp Quán Cafe Đà Lạt 2019 | View Đẹp | Cà Phê Ngon Nhất', 'cafe-da-lat-2019', '
<p>Cafe Đà Lạt 2019 đang là trào lưu và càng ngày càng được mở ra nhiều hơn. Những quán mới với nhiều phong cách khác nhau. Nhưng tất cả đều mang những nét đặc trưng riêng và chắc chắn đều xinh đẹp để thu hút khách hàng. Sau đây là những tổng hợp quán cafe đẹp</p>



<h2 class="wp-block-heading">Quán Của Thời Thanh Xuân Đà Lạt</h2>



<p>Quán Của Thời Thanh Xuân là một quán cafe đẹp với phong cách vintage, thoáng mát. Nơi mà hôm nay chúng ta tận hưởng những vị trà ngon, ngồi ở những ngôi nhà gỗ. Cái vị trà ấm, một ít bánh quy và thời tiết se se lạnh ở Đà Lạt thì còn gì hơn? Nhưng tại sao bạn không nên bỏ lỡ nơi này như bỏ lỡ thanh xuân của mình?</p>



<figure class="wp-block-image"><img decoding="async" src="https://www.homestaydalat.org/wp-content/uploads/2019/05/b%E1%BA%A3ng-hi%E1%BB%87u-qu%C3%A1n-c%E1%BB%A7a-th%E1%BB%9Di-thanh-xu%C3%A2n-1024x683.jpg" alt="Báº£ng hiá»u QuÃ¡n Cá»§a Thá»i Thanh XuÃ¢n"/></figure>



<p>Ngoài không gian và khung cảnh đẹp hay trà ngon, nơi đây còn là một dự án dành cho các bạn khiếm thính. Nhân viên đa phần đều không nghe hay nói chuyện được. Họ giao tiếp bằng ngôn ngữ cơ thể nhưng luôn tràn đầy năng lượng tươi sáng truyền đến bạn.</p>



<figure class="wp-block-image"><img decoding="async" src="https://www.homestaydalat.org/wp-content/uploads/2019/05/kh%C3%B4ng-gian-qu%C3%A1n-c%E1%BB%A7a-th%E1%BB%9Di-thanh-xu%C3%A2n-%C4%90%C3%A0-L%E1%BA%A1t-1024x683.jpg" alt="KhÃ´ng gian QuÃ¡n Cá»§a Thá»i Thanh XuÃ¢n"/></figure>



<p>Quán nằm dưới một con dốc ở đường Triệu Việt Vương, cách chợ Đà Lạt khoảng 2km. Mức giá là &#8220;tùy lòng&#8221;. Ở đây nước đều không có bảng giá, bạn sẽ bỏ tùy thích vào một hộp gỗ. Hãy trả mức giá phù hợp với thứ mà bạn nhận được khi đến Quán của thời thanh xuân. Chắc chắn đây là quán cafe Đà Lạt 2019 ý nghĩa nhất.</p>



<p>Review chi tiết: <a href="https://huynhhieutravel.com/quan-cua-thoi-thanh-xuan-da-lat/" target="_blank" rel="noreferrer noopener" aria-label=" (mở trong tab mới)">https://huynhhieutravel.com/quan-cua-thoi-thanh-xuan-da-lat/</a> </p>



<figure><iframe width="560" height="315" src="https://www.youtube.com/embed/jT3UED_0PkA" allowfullscreen=""></iframe></figure>



<p>Địa chỉ: 9 Đường Triệu Việt Vương, Phường 4, Thành phố Đà Lạt.</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3903.6260604878826!2d108.42630511429559!3d11.931091040082222!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31711334da3732ef%3A0x9499ee6f3dd5051a!2zUXXDoW4gQ-G7p2EgVGjGocyAaSBUaGFuaCBYdcOibg!5e0!3m2!1svi!2s!4v1560736447342!5m2!1svi!2s" width="600" height="450" allowfullscreen=""></iframe></figure>



<h2 class="wp-block-heading">Một Mình Cafe</h2>



<p>Đây là quán cafe có tên gội &#8220;MỘT MÌNH&#8221; chứ không phải bạn sẽ đi MỘT MÌNH cafe đâu nhé! Nói đùa vậy thôi chứ chắc chắn chủ nhân ở đây muốn xây dựng lên một quán cafe dành cho những người một mình.</p>



<figure class="wp-block-image"><img decoding="async" src="https://www.homestaydalat.org/wp-content/uploads/2019/06/pha-ch%E1%BA%BF-nh%E1%BB%AFng-ly-cafe-cho-kh%C3%A1ch-%E1%BB%9F-cafe-m%E1%BB%99t-m%C3%ACnh-%C4%91%C3%A0-l%E1%BA%A1t.jpg" alt="Pha cháº¿ nhá»¯ng ly cafe cho khÃ¡ch á» cafe Má»t MÃ¬nh"/></figure>



<p>Một không gian riêng tư ấm cúng với căn nhà gỗ. Nơi luôn có những mẻ bánh ngọt mới vào mỗi ngày và hương vị cafe làm ngây ngất lòng người. Ngoài ra, sân vườn khá rộng vì quán nằm bên trong một homestay khá đẹp. Bạn có thể dạo xung quanh và có cả bậc thang đi xuống khu vườn khác.</p>



<figure class="wp-block-image"><img decoding="async" src="https://www.homestaydalat.org/wp-content/uploads/2019/06/%C4%91%C6%B0%E1%BB%9Dng-%C4%91i-t%E1%BB%AB-nh%C3%A0-ra-s%C3%A2n-v%C6%B0%E1%BB%9Dn-%E1%BB%9F-coffee-m%E1%BB%99t-m%C3%ACnh-%C4%91%C3%A0-l%E1%BA%A1t-1024x575.jpg" alt="ÄÆ°á»ng Äi tá»« nhÃ  ra sÃ¢n vÆ°á»n Cafe Má»t MÃ¬nh ÄÃ  Láº¡t"/></figure>



<p>View đồi khá thoáng (Tuy không quá đẹp vì nhà cửa khá nhiều). Ngoài vườn cũng có nhiều không gian bàn ghế riêng khá thoáng mát. Không hẳn chỉ đi một mình, rủ rê bạn bè cùng đến đây cũng khá thú vị đấy! Địa chỉ của quán cũng không quán xa chợ Đà Lạt (Khoảng hơn 2km). Chắc chắn đây là một không gian riêng tư cafe Đà Lạt 2019 tuyệt nhất. </p>



<figure class="wp-block-image"><img decoding="async" src="https://www.homestaydalat.org/wp-content/uploads/2019/06/nh%E1%BB%AFng-tia-s%C3%A1ng-len-l%E1%BB%8Fi-quanh-ng%C3%B4i-nh%C3%A0-bu%E1%BB%95i-tr%C6%B0a-1024x575.jpg" alt="Nhá»¯ng tia sÃ¡ng len lá»i quanh ngÃ´i nhÃ  buá»i trÆ°a"/></figure>



<p>Review chi tiết quán cafe Một Mình: <a rel="noreferrer noopener" aria-label=" (mở trong tab mới)" href="https://www.homestaydalat.org/cafe-mot-minh-1206/" target="_blank">https://www.homestaydalat.org/cafe-mot-minh-1206/</a></p>



<figure><iframe width="560" height="315" src="https://www.youtube.com/embed/yi6R_77kL0U" allowfullscreen=""></iframe></figure>



<h2 class="wp-block-heading">Up Cafe</h2>



<p>Một quán cafe trên cao, nằm trên một con dốc với thung lũng và đường đèo bao vây xung quanh. Mang những điều tuyệt nhất là view thung lũng cùng đồi núi, bầu trời và cây cối. Up cafe thổi vào hồn những người mộng lên Đà Lạt tìm kiếm thứ mình còn thiếu.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="598" height="398" src="https://media.huynhhieutravel.com/view-nhìn-ra-cực-kỳ-thoáng-đãng-ở-Up-Coffee-Đà-Lạt.jpg" alt="View nhìn ra cực kỳ thoáng đãng ở Up Coffee Đà Lạt" class="wp-image-2267"/><figcaption>View nhìn ra cực kỳ thoáng đãng ở Up Coffee Đà Lạt</figcaption></figure>



<p>Quán có nội thất khá ổn, đa phần cửa kiếng nhìn thấu ra bên ngoài. Không gian yên tĩnh để làm việc. Đặc biệt pha chế ở đây cũng khá ổn, nước khá ngon và có cả socola bán kèm theo trong menu. Chắc chắn đây là một trong những quán cafe Đà Lạt 2019 có view đẹp nhất.</p>



<p>Review chi tiết tại:  <a rel="noreferrer noopener" aria-label=" (mở trong tab mới)" href="https://huynhhieutravel.com/up-coffee-da-lat/" target="_blank">https://huynhhieutravel.com/up-coffee-da-lat/</a> </p>



<figure><iframe width="560" height="315" src="https://www.youtube.com/embed/D030d_DrmT0" allowfullscreen=""></iframe></figure>



<p>Tham khảo thêm những review chất lượng về homestay Đà Lạt tại đây:  <a href="https://www.homestaydalat.org/" target="_blank" rel="noreferrer noopener" aria-label=" (mở trong tab mới)">https://www.homestaydalat.org/</a> </p>



<h2 class="wp-block-heading">La Viet cafe</h2>



<p>Một quán cafe dành cho những ai thật sự yêu và thưởng thức cafe. La Viet với một công xưởng cafe bên trong quán. Một nơi mà pha chế với những công thức cafe chuẩn mực và những thiết bị pha cafe chất lượng.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="598" height="600" src="https://media.huynhhieutravel.com/la-viet-da-lat.jpg" alt="La Viet Đà Lạt" class="wp-image-2338" srcset="https://media.huynhhieutravel.com/la-viet-da-lat.jpg 598w, https://media.huynhhieutravel.com/la-viet-da-lat-150x150.jpg 150w" sizes="(max-width: 598px) 100vw, 598px" /><figcaption>La Viet Đà Lạt</figcaption></figure>



<p>Không gian của quán cũng khá ổn với cảm giác thoải mái và thân thiện nhưng tràn ngập sự trẻ trung. Quầy pha chế show ra nơi dễ nhìn nhất. Bạn sẽ được tận mắt thấy các công đoạn pha chế cafe cẩn thận ở đây. Chắc chắn đây là một trong những quán cafe Đà Lạt 2019 pha chế ngon nhất.</p>



<p>Review chi tiết cafe La Viet: <a rel="noreferrer noopener" aria-label=" (mở trong tab mới)" href="https://huynhhieutravel.com/la-viet-coffee-da-lat/" target="_blank">https://huynhhieutravel.com/la-viet-coffee-da-lat/</a> </p>



<h2 class="wp-block-heading">An Cafe</h2>



<p>An cafe nằm trên một con dốc đường 3/2, khá gần chợ Đà Lạt. Không gian thiên nhiên của quán với những vườn cây xây và đá cuội trải trên mặt đường làm người ta dễ chịu. Đặc biệt quán trồng thủy canh nhiều loại rau xanh rất tuyệt vời. Những chậu hoa nhỏ nhỏ xinh xinh được rải đều khắp quán.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="599" height="597" src="https://media.huynhhieutravel.com/không-gian-xanh-ở-An-Coffee-đà-lạt.jpg" alt="Không gian xanh ở An Cafe Đà Lạt" class="wp-image-2329" srcset="https://media.huynhhieutravel.com/không-gian-xanh-ở-An-Coffee-đà-lạt.jpg 599w, https://media.huynhhieutravel.com/không-gian-xanh-ở-An-Coffee-đà-lạt-150x150.jpg 150w" sizes="(max-width: 599px) 100vw, 599px" /><figcaption>Không gian xanh ở An Cafe Đà Lạt</figcaption></figure>



<p>Nước uống cũng khá là ổng với nhiều loại trà, cafe và đặc biệt là những món sinh tố, detox cực kỳ chất lượng. Uống vào bạn sẽ thấy khỏe khoắn và cảm giác thiên nhiên hòa mình cùng cơ thể. Chắc chắn đây là một quán cafe Đà Lạt 2019 có nội thất tuyệt nhất.</p>



<p>Review chi tiết An Cafe: <a rel="noreferrer noopener" aria-label=" (mở trong tab mới)" href="https://huynhhieutravel.com/an-cafe-da-lat/" target="_blank">https://huynhhieutravel.com/an-cafe-da-lat/</a> </p>



<h2 class="wp-block-heading">Sunshine Cafe</h2>



<p>Sunshine nằm trên một con dốc cao với view thoáng nhìn ra Hồ Xuân Hương khá ổn. Không gian không những thoáng mát mà nội thất thiết kế khá ổn. Nó thiết kế phong cách boho với những phòng có bàn thấp và thảm lót. </p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="594" height="596" src="https://media.huynhhieutravel.com/nội-thất-trang-trí-rất-sặc-sở-của-sunshine-coffee-dalat.jpg" alt="Nội thất trang trí rất sặc sở của sunshine coffee Đà Lạt" class="wp-image-2313" srcset="https://media.huynhhieutravel.com/nội-thất-trang-trí-rất-sặc-sở-của-sunshine-coffee-dalat.jpg 594w, https://media.huynhhieutravel.com/nội-thất-trang-trí-rất-sặc-sở-của-sunshine-coffee-dalat-150x150.jpg 150w" sizes="(max-width: 594px) 100vw, 594px" /><figcaption>Nội thất trang trí rất sặc sở của sunshine coffee Đà Lạt</figcaption></figure>



<p>Đặc biệt các loại bánh ở đây khá ngon và khi uống cùng với trà cũng rất tuyệt vời. Đặc biệt với một số loại bánh đơn giản, nếu đến đúng thời gian bạn còn được hướng dẫn tự tay là nó. Ngồi đọc sách và ăn bánh mình làm cũng có những nét thú vị đặc biệt đúng không?</p>



<p>Review chi tiết Sunshine Cafe:  <a rel="noreferrer noopener" aria-label=" (mở trong tab mới)" href="https://huynhhieutravel.com/sunshine-coffee-da-lat/" target="_blank">https://huynhhieutravel.com/sunshine-coffee-da-lat/</a> </p>



<h2 class="wp-block-heading">F Cánh Đồng Hoa</h2>



<p>Giữa cánh đồng hoa và rừng thông yên tĩnh, bổng mọc lên một quán cafe cực đẹp. Một nơi có view thoáng mát, nguyên liệu đa phần từ gỗ. Những chiếc bàn dài được rải đều khắp quán với những màn bạc bao bọc xung quanh. Giống như một nhà kính cỡ lớn vậy.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="598" height="449" src="https://media.huynhhieutravel.com/không-gian-siêu-đẹp-của-cafe-F-cánh-đồng-hoa.jpg" alt="Không gian siêu đẹp của quán cafe F Cánh Đồng Hoa Đà Lạt" class="wp-image-2282"/><figcaption>Không gian siêu đẹp của quán cafe F Cánh Đồng Hoa Đà Lạt</figcaption></figure>



<p>Đặc biệt với những tiểu cảnh đặc biệt, những con đường gỗ, con đường kính bắt ra bêun ngoài nhìn thẳng cánh đồng. Bạn chắc chắn sẽ có những bức hình cực kỳ tuyệt vời với like khủng khi đến đây.</p>



<p>Chi tiết review:  <a rel="noreferrer noopener" aria-label=" (mở trong tab mới)" href="https://huynhhieutravel.com/quan-cafe-f-canh-dong-hoa-da-lat/" target="_blank">https://huynhhieutravel.com/quan-cafe-f-canh-dong-hoa-da-lat/</a> </p>



<h2 class="wp-block-heading">Sunny Farm</h2>



<p>Cầu thang vô cực đầu tiên ở Đà Lạt tại Sunny Farm đã tạo nên một trào lưu cực lớn lúc bấy giờ. Nơi đây ngoài điểm chụp hình thu hút đó thì view và không gian cũng cực kỳ ấn tượng. Những chậu hoa và cây xanh được bao phủ khắp quán.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/khung-cảnh-nên-thơ-ở-cafe-nông-trại-vui-vẻ-sunny-farm-đà-lạt.jpg" alt="Khung cảnh nên thơ ở cafe Nông Trại Vui Vẻ Sunny Farm Đà Lạt" class="wp-image-2084" srcset="https://media.huynhhieutravel.com/khung-cảnh-nên-thơ-ở-cafe-nông-trại-vui-vẻ-sunny-farm-đà-lạt.jpg 960w, https://media.huynhhieutravel.com/khung-cảnh-nên-thơ-ở-cafe-nông-trại-vui-vẻ-sunny-farm-đà-lạt-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Khung cảnh nên thơ ở cafe Nông Trại Vui Vẻ Sunny Farm Đà Lạt</figcaption></figure>



<p>Đặc biệt nơi đây còn có nhiều loại trò chơi thú vị như rút gỗ, ma sói, uno hay mèo nổ. Chắc chắn bạn sẽ có những buổi chơi boardgame thú vị cùng bạn bè khi đến đây. Hoặc lựa chọn những khu vực riêng tư để trò chuyện hay đọc sách cũng khá ok.</p>



<p>Review chi tiết:  <a rel="noreferrer noopener" aria-label=" (mở trong tab mới)" href="https://huynhhieutravel.com/cau-thang-vo-cuc-da-lat-o-cafe-nong-trai-vui-ve-sunny-farm/" target="_blank">https://huynhhieutravel.com/cau-thang-vo-cuc-da-lat-o-cafe-nong-trai-vui-ve-sunny-farm/</a> </p>



<h2 class="wp-block-heading">Panorama</h2>



<p>Panorama có không gian độc đáo nằm ở gần Trại Mát. Nó cách hơi xa thành phố với khoảng cách gần 8km nhưng sẽ là trải nghiệm thú vị khi bạn đi tham quan chùa Linh Phước (Gần đó).</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="597" height="399" src="https://media.huynhhieutravel.com/cafe-panorama.jpg" alt="Cafe Panorama" class="wp-image-2041"/><figcaption>Cafe Panorama</figcaption></figure>



<p>Nơi đây kiến trúc không quá nhiều sự đặc biệt. Nhiều bàn ghế trải đều khắp nơi, ở giữa là quầy pha chế. Xung quanh tường kính để khách có thể dễ dàng nhìn ra bên ngoài. Vì bên ngoài view cực kỳ đẹp. Một thung lũng với nhiều đồi núi và mây trời chập chùng phía xa. Đặc biệt ở đây cực kỳ lung linh bởi những nhà kính trồng hoa lên đèn vào buổi tối.</p>



<p>Review chi tiết:  <a rel="noreferrer noopener" aria-label=" (mở trong tab mới)" href="https://huynhhieutravel.com/cafe-panorama-da-lat/" target="_blank">https://huynhhieutravel.com/cafe-panorama-da-lat/</a> </p>
', 'Cafe Đà Lạt 2019 đang là trào lưu và càng ngày càng được mở ra nhiều hơn. Những quán mới với nhiều phong cách khác nhau. Nhưng tất cả đều mang những nét đặc trưng riêng và chắc chắn đều xinh đẹp để thu hút khách hàng. Sau đây là những tổng hợp quán cafe [&hellip;]', 2339, 'post', '2019-06-17 10:18:52', '2023-04-23 12:46:09');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (5031, 34);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (4995, 'Lễ Hội Phủ Giày Nam Định', 'le-hoi-phu-giay', '
<p>Lễ Hội Phủ Giầy đươc tổ chức hàng năm vào tháng 3 âm lịch. Lễ hội nhằm tôn vinh &#8220;Mẫu&#8221; Liễu Hạnh. Một nhân vật tín ngưỡng nằm trong hàng Tứ bất tử được người dân Việt Nam suy tôn: Thánh Tản Viên, Thánh Gióng, Tiên Chử Đồng Tử và Mẫu Liễu Hạnh. Đặc biệt lễ hội mang một ý nghĩa tâm linh to lớn trong lòng người dân xứ Nam Định.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/giới-thiệu-lễ-hội-phủ-giầy-1024x682.jpg" alt="Giới thiệu lễ hội Phủ Giầy" class="wp-image-5013" srcset="https://media.huynhhieutravel.com/giới-thiệu-lễ-hội-phủ-giầy.jpg 1024w, https://media.huynhhieutravel.com/giới-thiệu-lễ-hội-phủ-giầy-768x512.jpg 768w, https://media.huynhhieutravel.com/giới-thiệu-lễ-hội-phủ-giầy-696x464.jpg 696w, https://media.huynhhieutravel.com/giới-thiệu-lễ-hội-phủ-giầy-631x420.jpg 631w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Giới thiệu lễ hội Phủ Giầy</figcaption></figure>



<h2 class="wp-block-heading">Lễ Hội Phủ Giày là gì</h2>



<p>Lễ hội Phủ Giầy được tổ chức để suy tôn Mẫu Liễu Nghi về những điều thiện mà làm từ khi còn sống. Và đặc biệt là để suy tôn sự linh thiêng của vị Thánh Mẫu này. Họ cầu mong một năm may mắn và nhiều tài lộc.</p>



<h2 class="wp-block-heading">Nơi diễn ra lễ hội Phủ Giầy</h2>



<p>Địa điểm diễn ra lễ hội Phủ Giầy tại Phủ Dầy, xã Kim Thái, huyện Vụ Bản, tỉnh Nam Định. Tham khảo địa chỉ trên <a rel="noreferrer noopener" aria-label="Google Maps (mở trong tab mới)" href="https://goo.gl/maps/4tgCwizeppxh1n4n9" target="_blank">Google Maps</a>.</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3740.6893097027005!2d106.07946491439637!3d20.35444981583185!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3135df46aaaaaaab%3A0x90ca8fda466a42c3!2zUGjhu6cgROG6p3k!5e0!3m2!1svi!2s!4v1559876277518!5m2!1svi!2s" width="600" height="450" allowfullscreen=""></iframe></figure>



<h2 class="wp-block-heading">Thời gian diễn ra lễ hội Phủ Giầy</h2>



<p>Lễ hội Phủ Giầy diễn ra vào ngày 1/3 đến ngày 10/3 âm lịch hàng năm. Thời gian diễn ra lễ hội chính vào ngày 10/3 âm lịch.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="768" src="https://media.huynhhieutravel.com/lễ-khai-mạc-hội-phủ-giầy-1024x768.jpg" alt="Lễ khai mạc" class="wp-image-5016" srcset="https://media.huynhhieutravel.com/lễ-khai-mạc-hội-phủ-giầy-1024x768.jpg 1024w, https://media.huynhhieutravel.com/lễ-khai-mạc-hội-phủ-giầy-80x60.jpg 80w, https://media.huynhhieutravel.com/lễ-khai-mạc-hội-phủ-giầy-265x198.jpg 265w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Lễ khai mạc lễ hội Phủ Giầy</figcaption></figure>



<h2 class="wp-block-heading">Nguồn gốc lễ hội Phủ Giầy</h2>



<p>Khi mùa xuân đến, những cánh đồng lúa bát ngát phủ xanh cả một vùng đồng bằng, những sức sống mới đâm chồi nẩy nở. Cái nguồn sống tâm linh của những người dân xứ Nam Định cũng bắt đầu dâng đầy với nhiều lễ hội diễn ra. Phủ Giầy dần trở thành một lễ hội không thể thiếu được khi xuân về của người Nam Định và những người miền Bắc.</p>



<p>Phủ Giầy trước đây có tên là Kẻ Giầy, nơi suy tôn Liễu Hạnh. Sau này khi Liễu Hạnh được phong thành Mẫu Nghi của đất Việt, Chế Thắng Hòa diệu Đại vương và sắc phong Thượng đẳng tối linh thành. Nơi đây cũng đổi tên từ Phủ Giầy thành Kẻ Giầy.</p>



<p>Phủ Giầy có nghĩa là đền lớn của Kẻ Giày. Không rõ Phủ Giày được xây từ năm nào. Chỉ biết rằng năm 1557 thời vua Lê Anh Tông nhà Lê nơi đây vì xích mích giữa người dân nên chia làm 2 xã Tiên Hương và Vân Cát. Sau này Phủ Giầy cũng chia kiến trúc thành 2 khu vực riêng tên là phủ Tiên Hương và phủ Vân Cát.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="515" src="https://media.huynhhieutravel.com/lễ-hội-phủ-giầy-được-tổ-chức-hoành-tráng-1024x515.jpg" alt="Lễ hội Phủ Giầy được tổ chức hoành tráng năm 2019" class="wp-image-5015"/><figcaption>Lễ hội Phủ Giầy được tổ chức hoành tráng năm 2019</figcaption></figure>



<h3 class="wp-block-heading">Phủ Giầy hay Phủ Dày là đúng</h3>



<p>Tuy vậy, ngày nay nhiều đền chùa thường gắn với cái tên Phủ Dày. Cái tên sai với nguồn gốc nhưng lại dễ độc và dễ ghi hơn rất nhiều. Dần dần cái tên sai đó được phổ cập rộng hơn cả cái tên đúng là Phủ Giầy. Nên hiện nay cái tên Phủ Dày không hẳn là sai theo thuyết nhiều người dùng sẽ trở thành đúng. Nhưng cho tôi mạn phép dùng đúng phương ngữ và từ chính xác từ xưa đến nay là PHỦ GIẦY.</p>



<h3 class="wp-block-heading">Truyền thuyết Mẫu Liễu Hạnh</h3>



<p>Theo truyền thuyết kể lại, Liễu Hạnh nguyên là công chúa Quỳnh Hoa &#8211; con gái Ngọc Hoàng. Sau này vì đánh rơi chén ngọc nên bị giáng xuống trần vào năm 1557. Cô đầu thai vào nhà Lê Thái Công với cái tên Giáng Tiên. Giống như cái tên và nguồn gốc của nàng. Sắc đẹp của nàng thanh cao, nho nhã như tiên giáng trần. Tài năng thơ ca, đàn hát đều đầy đủ. Nàng nhiều lần xướng họa văn ca cùng chồng là Đào Lan và những bậc nho giả đại tài thời đó như Phùng Khắc Khoan.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="864" src="https://media.huynhhieutravel.com/lễ-hội-phủ-giầy-thập-niên-90-1024x864.jpg" alt="Lễ hội Phủ Giầy Nam Định thập niên 90" class="wp-image-5021" srcset="https://media.huynhhieutravel.com/lễ-hội-phủ-giầy-thập-niên-90.jpg 1024w, https://media.huynhhieutravel.com/lễ-hội-phủ-giầy-thập-niên-90-768x648.jpg 768w, https://media.huynhhieutravel.com/lễ-hội-phủ-giầy-thập-niên-90-696x587.jpg 696w, https://media.huynhhieutravel.com/lễ-hội-phủ-giầy-thập-niên-90-498x420.jpg 498w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Lễ hội Phủ Giầy Nam Định thập niên 90</figcaption></figure>



<p>Về sau, nàng xuất gia nương cửa Phật và nhiều lần giúp dân trừ bệnh dịch. Nàng đi nhiều nơi làm điều thiện giúp nhiều người nghèo khó. Từ đó người dân khắp nơi suy tôn nàng lên hàng Thánh Mẫu, Mẫu Liễu và lập đền thờ. Đặc biệt đền thờ nơi nàng sinh ra được gọi là Kẻ Giầy (về sau đổi tên thành Phủ Giầy). Hoặc khá nổi tiếng là Phủ Tây Hồ (Ở Hà Nội), nơi Mẫu trước đây hay ghé thăm bình thơ cùng các bậc nho giả.</p>



<h2 class="wp-block-heading">Những hoạt động trong lễ hội</h2>



<p>Mỗi dịp xuân về, từ khắp các tỉnh thành miền Bắc đều tập trung người trẫy hội, hành hương dự lễ hội Phủ Giầy. Họ vừa du lịch tham quan vừa cầu mong Mẫu Liễu Hạnh ban cho những điều phước lành và mau mắn trong cuộc sống.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/đoàn-rước-lễ-hội-phủ-giầy-nam-định-1024x853.jpg" alt="Rước Mẫu" class="wp-image-5019"/><figcaption>Rước Mẫu lễ hội Phủ Giầy</figcaption></figure>



<h3 class="wp-block-heading">10 ngày lễ hội Phủ Giầy</h3>



<p>Lễ hội kéo dài trong 10 ngày từ mùng 1/3 đến 10/3 âm lịch tại Phủ Giầy.</p>



<ul class="wp-block-list"><li>Mùng 1: Lễ nhập hội. Họ Trần Lê (Dòng họ của Mẫu Liễu) vào làm lễ tại Phủ Chính rồi sang nơi thờ họ Lê ở phủ Nội và phủ Ngoại. Phủ Vân Cát cũng làm lễ nhập hội và làng lo việc tế.</li><li>Mùng 2: Làng cử hành lễ vào buổi tối và kèm theo lễ rước nước với đuốc thắp sáng. Nước được lấy vào chum (chĩnh) về tắm tượng Thánh Mẫu (Hay còn gọi là lễ Mộc Dục).</li><li>Mùng 3: Ngày lễ chính giỗ Mẫu Liễu Hạnh và được tổ chức lễ ở phủ Tiên Hương. Lễ vật bao gồm: nhang đèn, hoa quả, 100 bánh giầy lớn, một con lợn sống. Trong ngày này phủ Vân Cát cũng làm lễ với lễ cúng: một trâu thui, một bò thui, một lợn luộc (Tam sinh), hoa quả và một trăm cặp bánh giày.</li><li>Mùng 4 và 5: Lễ tế tiếp, các chức sắc trong làng sẽ tế theo thứ tự định trước.</li><li>Mùng 6: Rước Thánh Mẫu từ phủ Tiên Hương đến chùa Gôi. Đám rước kéo dài gần 1km với quy mô lớn và trang trọng. Thành phần dự gồm nhà chùa (Hòa thượng), Mẫu Liễu (Đạo Tứ Phủ), các quan chức và các người hành nghề cúng đạo, kèm theo là đội lân sư rồng.</li></ul>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="858" src="https://media.huynhhieutravel.com/lễ-rước-Mẫu-phủ-giầy-1024x858.jpg" alt="Lễ rước Mẫu Phủ Giầy ngày xưa" class="wp-image-5020" srcset="https://media.huynhhieutravel.com/lễ-rước-Mẫu-phủ-giầy.jpg 1024w, https://media.huynhhieutravel.com/lễ-rước-Mẫu-phủ-giầy-768x644.jpg 768w, https://media.huynhhieutravel.com/lễ-rước-Mẫu-phủ-giầy-696x583.jpg 696w, https://media.huynhhieutravel.com/lễ-rước-Mẫu-phủ-giầy-501x420.jpg 501w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Lễ rước Mẫu Phủ Giầy ngày xưa</figcaption></figure>



<ul class="wp-block-list"><li>Mùng 7, 8 và 9: Trò chơi Kéo chữ được diễn ra. Đây là nét đặc trưng độc đáo của lễ hội Kẻ Giầy. Mỗi lần xếp chữ cần trên 100 phu cờ ăn mặc đồng phục chỉnh tề. Khăn xếp trên đầu (Chít khăn), áo vàng, thắt lưng xanh, quần trắng, xà cạp đỏ. Mỗi người cầm một cây gậy khoảng 2m. Sẽ có một người điều khiển gọi là tổng cờ. Khi trò chơi bắt đầu, chủ lễ sẽ xin Mẫu ra chữ sau đó tổng cờ ra lệnh phu cờ xếp theo chữ. </li></ul>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/trò-chơi-kéo-chữ-phủ-giầy-1024x853.jpg" alt="Trò chơi kéo chữ Phủ Giầy" class="wp-image-5017"/><figcaption>Trò chơi kéo chữ Phủ Giầy</figcaption></figure>



<p>Trong quá trình diễn ra ngày lễ, ngoài lễ chính thì người dân và chức sắc trong Phủ Giầy cũng tổ chức nhiều trò chơi khác: hát tuồng, chèo, trống quân hay tổ chức các cuộc thi võ đầy sôi động. </p>



<h3 class="wp-block-heading">Chợ Viềng</h3>



<p>Ngoài ra, người dân còn tổ chức chợ Viềng bày bán nhiều loại sản phẩm: thủ công mỹ nghệ, các vật dụng cúng Phủ Giầy và nhiều loại đồ vật khác nhau. Đặc biệt bày bán những loại đặc sản như bò thui, bánh dày.</p>



<p>Chợ Viềng ở Phủ Dầy không chỉ đơn thuần buôn bán kinh tế. Mà nó còn là đặc trưng văn hóa lâu đời của người dân. Ở đây không quá chú trọng việc mua rẻ hay đắt mà người hành hương muốn mua điều gì đó may mắn từ chợ.</p>



<p>Tham khảo thêm chi tiết về lễ hội Nghinh Cô ở Bà Rịa Vũng Tàu:  <a href="https://huynhhieutravel.com/le-hoi-nghinh-co/">https://huynhhieutravel.com/le-hoi-nghinh-co/</a> </p>



<h2 class="wp-block-heading">Kiến trúc Phủ Giầy</h2>



<p>Phủ Giầy có bộ 3 kiến trúc chính thờ Mẫu Liễu Hạnh: Phủ Tiên Hương (Phủ chính), phủ Vân Cát và Lăng Chúa Liễu.</p>



<h3 class="wp-block-heading">Phủ Tiên Hương</h3>



<p>Phủ Tiên Hương (Phủ chính) là công trình đẹp nhất. Trước phủ là một chiếc giếng tròn với một cột cờ ở giữa. Nó nối với một sân rộng với một hệ thống nghi môn trụ, trên đỉnh là lân và phụng. Kế đến là ba tòa nhà ngang: nhà chiêng, nhà trống và nhà bia. Một hồ bán nguyệt bao quanh với bình phong và hai cầu vượt đều bằng đá. </p>



<p>Điện thờ chính thờ Mẫu Tứ Phủ, Mẫu Thượng Thiên (Trời) ở giữa. Thờ Mẫu Địa (Đất) bên phải. Thờ Mẫu Thoải (Nước) bên trái. Thờ Mẫu Thượng Ngàn (Núi Rừng) ở phía trước.</p>



<h3 class="wp-block-heading">Phủ Vân Cát</h3>



<p>Phía trước phủ Vân Cát là một hồ bán nguyệt. Đi tiếp sẽ gặp ngũ môn. Trung tâm là nơi thờ Chúa Liễu. Khu vực bên trái thờ các tượng Phật và bên phải là đền thờ Lý Nam Đế.</p>



<h3 class="wp-block-heading">Lăng chúa Liễu</h3>



<p>Lăng chúa Liễu nằm bên cạnh phủ chính. Nơi đây phân ra thành một khu vực riêng hình chữ nhật. Tất cả công trình đều làm bằng đó với chạm trổ tỉ mỉ chi tiết. Ở giữa lăng là một ngôi mộ hình bát giác.</p>
', 'Lễ Hội Phủ Giầy đươc tổ chức hàng năm vào tháng 3 âm lịch. Lễ hội nhằm tôn vinh &#8220;Mẫu&#8221; Liễu Hạnh. Một nhân vật tín ngưỡng nằm trong hàng Tứ bất tử được người dân Việt Nam suy tôn: Thánh Tản Viên, Thánh Gióng, Tiên Chử Đồng Tử và Mẫu Liễu Hạnh. Đặc biệt [&hellip;]', 5014, 'post', '2019-06-07 06:13:59', '2023-04-23 12:31:13');
