INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (4966, 'Lễ Hội Nghinh Cô | Thời Gian | Địa Điểm | Đặc Trưng Bạn Cần Phải Biết', 'le-hoi-nghinh-co', '
<p>Lễ Hội Nghinh Cô thuộc một trong những lễ hội lớn nhất của người dân vùng biển miền Nam. Mỗi khi đến lễ hội, hàng nghìn ghe thuyền tụ hội lại vùng biển Long Hải, tỉnh Bà Rịa Vũng Tàu để tham gia. Ngoài ra, hàng vạn du khách hành hương đến đây vừa tắm biển vừa cúng viếng tạo thành khung cảnh tấp nập, nhộn nhịp. Hãy cùng Huynh Hieu Travel tìm hiểu về lễ hội Nghinh Cô độc đáo này nhé!</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="800" height="534" src="https://media.huynhhieutravel.com/lễ-hội-dinh-cô.jpg" alt="Lễ hội Dinh Cô" class="wp-image-4983" srcset="https://media.huynhhieutravel.com/lễ-hội-dinh-cô.jpg 800w, https://media.huynhhieutravel.com/lễ-hội-dinh-cô-768x513.jpg 768w, https://media.huynhhieutravel.com/lễ-hội-dinh-cô-696x465.jpg 696w, https://media.huynhhieutravel.com/lễ-hội-dinh-cô-629x420.jpg 629w" sizes="(max-width: 800px) 100vw, 800px" /><figcaption>Lễ hội Dinh Cô</figcaption></figure>



<h2 class="wp-block-heading">Lễ Hội Nghinh Cô là gì</h2>



<p>Lễ Hội Nghinh Cô là lễ hội nước lớn nhất vùng ven biển Nam Bộ của người dân Dinh Cô &#8211; Long Hải &#8211; Vũng Tàu. Lễ hội này gắn liền với một nhân vật Cô trong truyền thuyết dân gian và rất hiển linh. Ngoài việc cúng bái tại dinh thờ Cô, lễ hội còn tổ chức đoàn thuyền lớn trang nghiêm đón rước linh đình trên mặt biển tương tự lễ hội Nghinh Ông.</p>



<p style="text-align:left">Hàng năm lễ hội luôn thu hút hàng trăm nghìn người hành hương từ khắp các tỉnh ven biển miền Nam đến cúng bái. Hoặc từ các biển miền trung như Phan Rí, Phan Thiết cũng đến đây hành hương.</p>



<p>Đây cũng là đặc trưng khác biệt khá lớn với lễ hội Nghinh Ông ở các làng chài ven biển. Ở mỗi làng chài đều có đền, lăng, miếu xương cá Ông riêng biệt. Vì vậy người dân ven biển không cần tụ tập quá đông đúc tại một khu vực như lễ hội Nghinh Cô.</p>



<p>Đặc biệt, lễ hội Nghinh Cô trở nên phổ biến hơn là vì Long Hải cũng là một bãi biển khá đẹp và thu hút khách du lịch. Vì thế nhiều khách du lịch vừa đến tắm biển, vừa kết hợp hành hương, khấn vái. Đây cũng là lễ hội thể hiến tín ngưỡng thờ Mẫu từ xa xưa của người dân Việt Nam ta.</p>



<h2 class="wp-block-heading">Địa điểm diễn ra lễ hội Nghinh Cô</h2>



<p>Lễ Nghinh Cô được tổ chức ở Dinh Cô, Ấp Hải Sơn, thị trấn Long Hải, tỉnh Bà Rịa &#8211; Vũng Tàu. Bạn có thể tham khảo địa chỉ trên <a rel="noreferrer noopener" aria-label="Google Maps (mở trong tab mới)" href="https://goo.gl/maps/b9DjLawY2V6DwNcC8" target="_blank">Google Maps</a>.</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d7848.878649277953!2d107.22984712880107!3d10.386638776523295!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x317576f3b563887d%3A0xe6a0c31b9970f296!2zRGluaCBDw7Q!5e0!3m2!1svi!2s!4v1559461301305!5m2!1svi!2s" width="600" height="450" allowfullscreen=""></iframe></figure>



<h2 class="wp-block-heading">Nguồn gốc lễ hội Nghinh Cô</h2>



<p>Cô có tên là Lê Thị Hồng Thủy. Theo truyền thuyết dân gian, cô là người con gái Bình Thuận theo cha vào vùng Bà Rịa Vũng Tàu buôn bán. Sau đó cô yêu mến dần cảnh quan biển nước hữu tình, con người chất phát vùng biển Bà Rịa và mong muốn được định cư tại vùng biển này. Tuy vậy, cha cô kiên quyết bắt cô trở về vùng quê nhà Bình Thuận. Sau đó cô vì buồn phiền mà buông mình vào vùng biển Mũi Nhỏ tự vẫn. Sau này cô hiển linh, giúp đỡ nhiều ngư dân vùng biển này và được dựng miếu thờ.</p>



<p>Cũng có người bảo rằng cô là một liên lạc viên của quân Tây Sơn, giữ liên lạc giữa các vùng biển miền Trung. Sau này bị quân nhà Nguyễn phát hiện và giết chết. Sau đó cô hiển linh giúp đỡ ngư dân qua lại vùng biển này.</p>



<p>Như vậy, có nhiều câu chuyện truyền thuyết khác nhau do dân gian lưu truyền kể về xuất xứ của cô. Nhưng ta có thể tổng hợp lại rằng ngày cô chết là 12/2 âm lịch (Ngày diễn ra lễ hội Nghinh Cô) và chuyện xả ra vào năm 1804 khi cô 16 tuổi.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="720" src="https://media.huynhhieutravel.com/mộ-cô-long-hải-1024x720.jpg" alt="Mộ Cô Long Hải" class="wp-image-4982" srcset="https://media.huynhhieutravel.com/mộ-cô-long-hải-1024x720.jpg 1024w, https://media.huynhhieutravel.com/mộ-cô-long-hải-370x260.jpg 370w, https://media.huynhhieutravel.com/mộ-cô-long-hải-100x70.jpg 100w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Mộ Cô Long Hải</figcaption></figure>



<p>Những điểm giống nhau của câu chuyện là mô tả cô là người con gái trẻ, chết oan ở biển và thường hiển linh giúp đỡ ngư dân vùng biển. Thêm vào đó, mỗi khi đi biển gặp may được những vụ bội thu tôm cá hay thoát chết khỏi những cơn bão lớn người dân sẽ mở tiệc lớn. Họ tổ chức hát bội, ăn mừng linh đình. Vì vậy, tiếng lành dần đồn xa và Cô trở thành một sự tồn tại linh thiêng.</p>



<h2 class="wp-block-heading">Những hoạt động ở lễ hội Nghinh Cô</h2>



<p>Thời gian gian diễn ra lễ hội Nghinh Cô là vào ngày 10/2 đến 12/2 âm lịch hàng năm. Ngày lễ chính diễn ra vào 12/2 âm lịch.</p>



<p>Từ sáng ngày 10 những ngư dân và người hành hương dùng các phương tiện từ tàu thuyền, phương tiện đường bộ đến viếng. Những người chịu trách nhiệm cúng lễ thường tổ chức cúng tiên từ ngày này. Người dân đã được phép dân cúng những thường vật như hoa quả.</p>



<p>Đến ngày 11 thì bắt đầu đông đúc dần. Lễ cầu an cũng được tiến hành vào tối ngày 11. Các vị sư từ các chùa chiềng gần đó cũng tề tụ. Họ tụng kinh cầu quốc thái dân an, mong một mùa vụ đi biển bội thu và bình an. Lễ tụng kinh thường diễn ra đến nữa đêm. Bên ngoài Dinh Cậu, người dân cũng bắt đầu tổ chức những lễ hội hoa đăng náo nhiệt. Những ngọn đèn lớn và hoa đăng sáng rực khắp đường và bờ biển. Tiếng trống, lễ hội và âm nhạc khá linh đình, đôi khi còn có cả múa lân.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="810" src="https://media.huynhhieutravel.com/biển-dinh-cô-1024x810.jpg" alt="Biển Dinh Cô" class="wp-image-4984"/><figcaption>Biển Dinh Cô</figcaption></figure>



<p>Ngày 12 là lúc lễ hội chính diễn ra. Một vị Chánh tế dẫn đoàn từ Dinh Cô tiến về mé biển, tàu thuyền trang hoàng lộng lẫy chờ từ rạng sáng. Sẽ có một đội mặc lễ phục truyền thống, đầu đội mão, chân đi hia, mang kiệu son thếp vàng chở bài vị, có lọng che và quân cờ đi kèm hai bên theo sau. Tiếp sau đó là đoàn nhạc ngũ âm và đoàn chèo bả trạo với những bộ áo quần sặc sở. </p>



<p>Khi đến mé biển, cả đoàn sẽ tiến lên một thuyền lễ lớn được trang hoàng lộng lẫy. Trước mũi thuyền sẽ có hương án sơn đỏ, trên có lư hương và mâm trái cây. Những thành phần chính trong đoàn rước bao gồm Chánh tế sẽ tiến lên thuyền này. Còn lại những người khác sẽ tiến đến những ghe thuyền khác neo đậu gần đó.</p>



<p>Sau màn pháo nổ hoặc hồi chuông, Chánh tế sẽ cho thuyền khởi hành. Những chiếc ghe thuyền phía sau cũng nối đuôi nhau. Tiếng nổ đầu máy kéo hòa cũng tiếng nhạc ngũ cung rình rang. Sau đó là các tiếng trống, chiêng liên hồi nổ ra. Đoàn thuyền mang theo một không khí nhộn nhịp tiến ra vùng biển xanh vào buổi sáng sớm. Các thuyền sẽ tung lên trời các quả bóng bay đủ loại màu sắc, tạo thành một khung cảnh rộn ràng tuyệt vời.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="960" src="https://media.huynhhieutravel.com/toàn-cảnh-dinh-cô-1024x960.jpg" alt="Toàn cảnh Dinh Cô nơi tổ chức lễ hội Nghinh Cô" class="wp-image-4987"/><figcaption>Toàn cảnh Dinh Cô</figcaption></figure>



<p>Sau khi đoàn thuyền đi khoảng 1-2km, vị Chánh tế sẽ cho dừng lại, tạo thành một vòng tròn thuyền rộng. Vị Chánh tế và đội mặc lễ phục sẽ tiến về mũi thuyền làm lễ Nghinh Cô và vái mời Ông Nam Hải về dinh chứng kiến lòng thành của những người dân. Đội nhạc ngũ cung sẽ đệm, đội chèo bả cất tiếng hát, ca ngợi công đức của Cô và Ông Nam Hải. Họ cầu mong một năm mưa thuận gió hòa, bội thu tôm cá.</p>



<p>Sau đó các thuyền sẽ cho nổ pháo và trống hòa nhịp cùng. Tất cả tạo thành một không khí sôi nổi ở giữa biển khơi.</p>



<p>Khi thuyền trở về thì đoàn múa lân ở đất liền sẽ ra nghênh đoán, những người dân bên ngoài sẽ phất cờ, hò reo rình rang. Ngoài những chiếc bóng bay đủ màu sắc thả lên bầu trời thì những người dân hành hương cũng bắt đầu phóng sinh. Họ thả các loài chim lên dày đặc cả bầu trời.</p>



<p>Kiệu rước Cô được đưa thẳng về Dinh Cô, và làm lễ tế. Lễ vật dâng lên Cô bao gồm 1 heo quay, 1 con heo vừa được mổ, bánh trái, hoa quả, rượu trà. Sau đó tiến hành lễ dâng hương, rượu và trà. Tiếp theo là múa Tam hiền và Mâm vàng. Mộ Cô cũng được cúng hoa quả thanh tịnh. Sau lễ chính sẽ là lễ Xây chầu &#8211; Đại bội (Hát bội cả ngày lẫn đêm).</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="768" src="https://media.huynhhieutravel.com/bên-trong-mộ-cô-long-hải-bà-rịa-1024x768.jpg" alt="Bên trong Mộ Cô ở Long Hải" class="wp-image-4986" srcset="https://media.huynhhieutravel.com/bên-trong-mộ-cô-long-hải-bà-rịa.jpg 1024w, https://media.huynhhieutravel.com/bên-trong-mộ-cô-long-hải-bà-rịa-768x576.jpg 768w, https://media.huynhhieutravel.com/bên-trong-mộ-cô-long-hải-bà-rịa-80x60.jpg 80w, https://media.huynhhieutravel.com/bên-trong-mộ-cô-long-hải-bà-rịa-265x198.jpg 265w, https://media.huynhhieutravel.com/bên-trong-mộ-cô-long-hải-bà-rịa-696x522.jpg 696w, https://media.huynhhieutravel.com/bên-trong-mộ-cô-long-hải-bà-rịa-560x420.jpg 560w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Bên trong Mộ Cô ở Long Hải</figcaption></figure>



<p>Vào buổi chiều ở bãi biển cũng sẽ diễn ra lễ hội trò chơi dân gian như múa lân, đấu cờ, bắt vịt trên nước, bắt cá, bắt lương, đua thuyền, đua thúng, múa bông, múa quạt,&#8230;</p>



<p>Đa phần những buổi lễ Dinh Cô đều được giữ gìn các nét truyền thống từ trước đến nay. Tuy vậy vẫn có nhiều thay đổi theo thời đại. Như việc thả bong bóng đủ các màu sắc để trông phần rực rỡ hơn. Hay cũng có những biến chất của việc phóng sinh sau đó là bị người dân bắt lại.</p>



<p>Bạn có thể tham khảo thêm một số nơi linh thiêng khác ở miền Nam như:</p>



<ul class="wp-block-list"><li>Mẹ Nam Hải: <a rel="noreferrer noopener" aria-label="https://huynhhieutravel.com/me-nam-hai/ (mở trong tab mới)" href="https://huynhhieutravel.com/me-nam-hai/" target="_blank">https://huynhhieutravel.com/me-nam-hai/</a></li><li>Miếu Bà Chúa Xứ: <a href="https://huynhhieutravel.com/mieu-ba-chua-xu/" target="_blank" rel="noreferrer noopener" aria-label="https://huynhhieutravel.com/mieu-ba-chua-xu/ (mở trong tab mới)">https://huynhhieutravel.com/mieu-ba-chua-xu/</a></li></ul>



<h2 class="wp-block-heading">Kiến trúc Dinh Cô</h2>



<p>Ban đầu Dinh Cô chỉ là một miếu nhỏ lợp bằng lá cây. Lúc đầu Dinh Cô được xây dựng sát bờ biển. Nhưng năm 1930 có sự tranh chấp chủ quyền đất của người dân, Dinh Cô được dời lên phía triền núi.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="720" src="https://media.huynhhieutravel.com/dinh-cô-1024x720.jpg" alt="Dinh Cô" class="wp-image-4985" srcset="https://media.huynhhieutravel.com/dinh-cô-1024x720.jpg 1024w, https://media.huynhhieutravel.com/dinh-cô-370x260.jpg 370w, https://media.huynhhieutravel.com/dinh-cô-100x70.jpg 100w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Dinh Cô</figcaption></figure>



<p>Sau này người dân thờ cúng ngày càng nhiều. Vừa để tiện việc thăm viếng cô và tỏ lòng tôn trọng, những người hành hương đã quyên góp xây dựng nên một ngôi miếu khang trang hơn. Diện tích Dinh Cô ước tính khoảng 1.000m2  </p>



<p>Dinh Cô ngày nay được lớp ngói âm dương, có 3 tầng, bậc tam cấp bằng xi măng để đi lên xuống dễ dàng. Mặt trong tựa vào núi Thùy Vân, mặt ngoài nhìn ra biển Long Hải. Mỗi khi những ngư dân có việc đi ngang đây đều dừng lại và thắp nhan ngay trên tàu để cầu mong bình an.</p>



<p>Gian giữa Dinh Cô là tượng Cô, có 4 cô hầu gái đứng chầu hai bên. Bên phải là án thờ Ngũ Vị Nương Nương, bên trái là án thờ Tứ Pháp Nương Nương. Tường bên phải là thờ cha mẹ thân sinh của Cô. Tường bên trái thờ Chúa Cậu. Và gian bên cạnh là thờ Mẹ Sanh.</p>



<p>Ngoài chánh điện, Dinh Cô còn thờ Cửu Thiên Huyền Nữ, Quan Thế Âm Bồ Tát, Bác Hồ, Quan Thánh Đế Quân, Hỏa Tinh Thánh Mẫu, Chúa Tinh Nương Nương,&#8230;</p>



<p>Riêng phần Mộ Cô nằm cách Dinh Cô khoảng 1km. Đây cũng đã được xây cất khang trang hơn xưa. Hàng năm đều được nhiều người hành hương cúng bái. Đặc biệt những ai hành hương đến Dinh Cô đều không thể bỏ qua Mộ Cô.</p>
', 'Lễ Hội Nghinh Cô thuộc một trong những lễ hội lớn nhất của người dân vùng biển miền Nam. Mỗi khi đến lễ hội, hàng nghìn ghe thuyền tụ hội lại vùng biển Long Hải, tỉnh Bà Rịa Vũng Tàu để tham gia. Ngoài ra, hàng vạn du khách hành hương đến đây vừa tắm [&hellip;]', 4981, 'post', '2019-06-02 10:35:10', '2023-04-23 12:25:47');
