<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/chợ-nổi-cái-bè-tiền-giang-1024x682.jpg" alt="Giới thiệu chợ nổi Cái Bè Tiền Giang" class="wp-image-3794" srcset="https://media.huynhhieutravel.com/chợ-nổi-cái-bè-tiền-giang.jpg 1024w, https://media.huynhhieutravel.com/chợ-nổi-cái-bè-tiền-giang-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Giới thiệu chợ nổi Cái Bè Tiền Giang</figcaption></figure>



