INSERT OR IGNORE INTO PostTag (postId, tagId) VALUES (3025, 306);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (2990, 'Nam Du ở đâu? Có gì đặc biệt? THUYẾT MINH về nó', 'nam-du', '
<p><strong>Nam Du</strong> là quần thể 21 đảo lớn nhỏ. Nó nằm cách bờ <strong>thành phố Rạch Giá</strong> 65 hải lý. <strong>Diện tích đảo</strong> bao gồm 6,75km2. <strong>Dân số đảo </strong>khá nhỏ với khoảng hơn 8.000 người sinh sống. Nơi đây có đảo chỉ có 1 người sinh sống và còn được gọi là chúa đảo. Mật độ dân số của nó là 1.190 người/km2 (Ít hơn 5 lần so với Thành phố Hồ Chí Minh).</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/thuyết-minh-về-nam-du-1024x682.jpg" alt="Thuyết minh về Nam Du" class="wp-image-3839" srcset="https://media.huynhhieutravel.com/thuyết-minh-về-nam-du.jpg 1024w, https://media.huynhhieutravel.com/thuyết-minh-về-nam-du-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Thuyết minh về Nam Du</figcaption></figure>



<h2 class="wp-block-heading">Nam du là ở đâu</h2>



<p>Đảo Nam Du nằm ở vịnh Thái Lan và về hướng Đông Nam so với đảo Phú Quốc.  Dân gian vẫn có câu ca để mô tả về những hòn đảo lớn nhỏ ở đây.</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow"><p>Hòn Mấu đâm thấu Đô Nai<br>Đô Nai quay sang Bờ Đập<br>Bờ Đập tấp lại hòn Lò<br>Hòn Lò mò đến hòn Ngang<br>Hòn Ngang tạt sang hòn Đụng<br>Hòn Đụng cụng vào hòn Dầu<br>Hòn Dầu nằm chầu Bỏ Áo<br>Bỏ Áo tháo ngược hòn Ông<br>Hòn Ông dông đến hòn Dâm<br>Hòn Dâm đâm thẳng hòn Tre<br>Hòn Tre te đến hòn Mốc<br>Hòn Mốc xốc lại hòn Nhàn<br>Hòn Nhàn tràn thẳng hòn Hàn<br>Hòn Hàn quàng cổ ba hòn Nồm<br>Hòn Nồm chồm đại lên hòn Khô<br>Hòn Khô vô bãi Chệt<br>Bãi Chệt lết lên hòn Lớn&#8230;</p><cite>Trích thơ dân gian.<br></cite></blockquote>



<p>Tuy nơi đây có 21 đảo lớn nhỏ nhưng dân cư chỉ sinh sống ở 7 đảo chính là chủ yếu: hòn Bờ Đập, hòn Ngang, hòn Bỏ Áo, hòn Đụng Lớn, hòn Đụng Nhỏ, hòn Mấu. hòn Trung.</p>



<p>Tham khảo các homestay đẹp, giá rẻ ở đây: <a href="https://huynhhieutravel.com/homestay-nam-du">https://huynhhieutravel.com/homestay-nam-du</a></p>



<h2 class="wp-block-heading">Truyền thuyết ở Nam Du</h2>



<p>Đảo Nam Du là hòn đảo ngọc xinh đẹp, Nơi đây gắn với nhiều truyền thuyết, giai thoại thú vị.</p>



<div class="wp-block-image"><figure class="aligncenter"><img loading="lazy" decoding="async" width="591" height="596" src="https://media.huynhhieutravel.com/du-lịch-nam-du.jpg" alt="Du lịch Nam Du" class="wp-image-3841" srcset="https://media.huynhhieutravel.com/du-lịch-nam-du.jpg 591w, https://media.huynhhieutravel.com/du-lịch-nam-du-150x150.jpg 150w" sizes="(max-width: 591px) 100vw, 591px" /><figcaption>Du lịch Nam Du</figcaption></figure></div>



<h3 class="wp-block-heading">Những giai thoại gắn liền với vua Gia Long Nguyễn Ánh</h3>



<p>Giai thoại kể rằng, trước đây khi chạy trốn quân Tây Sơn, vua Gia Long cho quân xuôi về các đảo phía nam. Ông đi ngang qua một hòn đảo xinh đẹp, thấy bãi biển rộng lớn nên cho quân tạm trú nơi đây.</p>



<p>Trong thời gian lưu lại, lương thực và nước uống bắt đầu cạn kiệt. Ông cho quân lính đào giếng lấy nước, bới đất tìm khoai để ăn. Tình cờ ông phát hiện một loại củ tròn tròn nhưng không phải là khoai.</p>



<p>Sau một thời gian lên ngôi, ông nhớ đến hòn đảo xinh đẹp mình đã đặt chân. Ông ra chiếu chỉ đặt tên hòn đảo ông đặt chân đến là hòn Củ Tròn để tưởng nhớ thứ củ đã giúp ông sống sót ở đó. Sau này, người dân bắt đầu đọc chạy thành Củ Tron vì phát âm dễ hơn.</p>



<div class="wp-block-image"><figure class="aligncenter"><img loading="lazy" decoding="async" width="477" height="596" src="https://media.huynhhieutravel.com/du-lịch-nam-du-giá-rẻ.jpg" alt="Nơi đây có nhiều nơi tự sướng tuyệt vời" class="wp-image-3842"/><figcaption>Nơi đây có nhiều chỗ tự sướng tuyệt vời</figcaption></figure></div>



<h3 class="wp-block-heading">Xương cá Ông trên đồi cao bãi Ngự</h3>



<p>Năm 2017, một con cá Ông (cá Voi) bị chết ngoài biển. Theo truyền thuyết, ngư dân luôn tin tưởng cá Ông là loài cá linh thiêng. Nó luôn giúp đỡ những ngư dân bị đắm tàu hay kẹt ngoài biển khơi. Nó như một vị thần biển hiền hòa với những người ngư dân.</p>



<p>Vì vậy, họ đã tìm cách đưa xác cá Ông về đảo. Nhưng bao nhiêu tàu thuyền đều không di chuyển được. Sau đó, người ta khấn vái, mong cá Ông sẽ về an nghỉ ở đảo phù hộ. Thì lạ thay, xác cá Ông bỗng nhẹ nhàng hơn và người ta dễ dàng đem xác về đảo Nam Du.</p>



<p>Họ đem xác cá Ông lên đồi cao ở Bãi Ngự. Ngư dân cải táng và lập miếu thờ cá Ông. Hiện nay, bộ xương của cá Ông vẫn còn ở trên miếu thờ. Các bạn có thể lên cúng viếng cá Ông ở trên Bãi Ngự.</p>



<div class="wp-block-image"><figure class="aligncenter"><img loading="lazy" decoding="async" width="598" height="305" src="https://media.huynhhieutravel.com/nam-du.jpg" alt="Nam Du" class="wp-image-3844"/><figcaption>Nam Du</figcaption></figure></div>



<h2 class="wp-block-heading">Lịch sử Nam Du</h2>



<p>Nam du có từ lâu đời nhưng đến năm 2005 mới được chính thức trở thành một đơn vị hành chính của Việt Nam. Tên gọi của nó có nhiều giả thuyết, nhưng người ta nghiêng về cái tên bắt nguồn từ thời vua Gia Long. Nam Du là từ đọc chạy của nam dự, nghĩa là đảo ở phía nam.</p>



<p>Đảo Nam Du bắt đầu làm du lịch từ năm 2014, đến năm 2015 thì bùng nổ. Đến nay, khi nhắc các tuyến đảo miền Tây thì đây là lựa chọn hàng đầu các bạn trẻ du lịch. Tốc độ tăng trưởng du lịch của nó cũng vô cùng mạnh mẽ.</p>



<p>Năm 2014, chỉ với vài ngàn lượt khách du lịch nhưng tăng trưởng đến 25.000 &#8211; 26.000 lượt khách vào năm 2015. Đến năm 2017 đã có đến 119.000 lượt khách. Từ một hòn đảo hoang vu, Nam Du đã trở thành điểm du lịch thu hút với lượt khách mỗi năm gấp vài chục lần dân số của đảo.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/thuyết-minh-về-du-lịch-đảo-nam-du-1024x682.jpg" alt="Thuyết minh về du lịch đảo Nam Du" class="wp-image-3840" srcset="https://media.huynhhieutravel.com/thuyết-minh-về-du-lịch-đảo-nam-du.jpg 1024w, https://media.huynhhieutravel.com/thuyết-minh-về-du-lịch-đảo-nam-du-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Thuyết minh về du lịch đảo Nam Du</figcaption></figure>



<p>Bạn có thể tham khảo du lịch Nam du với địa điểm, cách du lịch, kinh nghiệm tại đây: <a href="https://huynhhieutravel.com/du-lich-nam-du">https://huynhhieutravel.com/du-lich-nam-du</a></p>



<h3 class="wp-block-heading">Những thay đổi tích cực mà nó mang lại</h3>



<p>Với những lượt khách du lịch lên đến hàng trăm nghìn, ước tính mỗi năm nó mang lại kinh tế Nam Du và Kiên Giang hàng trăm tỷ đồng. Đời sống người dân bắt đầu được cải thiện dần. Từ việc mưu sinh khó khăn với những chuyến đánh bắt xa bờ, họ đã có cách cải thiện đời sống của mình hơn.</p>



<p>Tham khảo cách du lịch tự túc Nam Du với lịch trình 2 ngày 1 đêm chi tiết tại đây: <a href="https://huynhhieutravel.com/du-lich-nam-du-gia-re">https://huynhhieutravel.com/du-lich-nam-du-gia-re</a></p>



<p>Nhiều người dân trong vùng đã hình thành liên kết với nhau. Nhiều người mở nhà nghỉ, khách sạn để khách du lịch lưu trú. Một số người thì dùng thuyền có sẳn, mua thêm cano để chở khách đi du lịch các đảo xa bờ. Những hải sản đánh bắt mang về cũng được tiêu thụ tốt và giá cả tăng hơn trước.</p>



<p>Dường như đời sống kinh tế của người dân ở đây càng ngày càng phát triển mạnh mẽ và khá giả hơn.</p>



<div class="wp-block-image"><figure class="aligncenter"><img loading="lazy" decoding="async" width="596" height="442" src="https://media.huynhhieutravel.com/homestay-nam-du.jpg" alt="Cảnh quan xinh đẹp" class="wp-image-3843"/><figcaption>Cảnh quan xinh đẹp</figcaption></figure></div>



<h3 class="wp-block-heading">Nhưng cũng có những tiêu cực ở Nam Du khi phát triển du lịch</h3>



<p>Năm 2016, hiện tượng cạn nước bắt đầu xuất hiện ở hòn đảo này. <a href="https://laodong.vn/xa-hoi/xa-dao-nam-du-kien-giang-nhung-ngay-nuoc-quy-hon-tien-528972.bld">Nam Du bị quá tải</a> vì lượt khách gấp vài lần đến hàng chục lần người dân bản xứ ùn ùn kéo đến đây. Các giếng nước bắt đầu khô cạn, nước trở nên hiếm hơn khi đúng dịp mùa khô. Giải pháp được đưa ra là vận chuyển nước từ đất liền vào giải quyết tạm thời nhu cầu, nhưng cũng không phải lâu dài.</p>



<p>Ngoài lượng nước, môi trường ở đây càng bị hủy hoại nghiệm trọng. Từ một hòn đảo hoang sơ, có lẽ Nam Du bắt đầu trở thành một hòn đảo hoang tàn. Rác rưới bị lượng lớn khách du lịch bỏ lại, không phân hủy được. Hòn đảo này lại không thể xử lý rác bằng công nghiệp mà chỉ có thể chôn xuống đất. Hoặc để nó chất cao thành những núi rác đầy mùi hôi.</p>



<p>Đảo Nam Du là hòn đảo xinh đẹp, tuy vậy chúng ta phải nhìn nhận hiện trạng du lịch tràn lan và tác hại nó mang lại. Người dân du lịch cần ý thức nhiều hơn và chính quyền cũng cần có nhiều hoạt động thiết thực để cải tổ môi trường đảo Nam Du.</p>



<p><strong>Liên hệ Huynh Hieu Travel: </strong></p>



<p>Fanpage: <a href="https://www.facebook.com/toidiphuotvn/">https://www.facebook.com/toidiphuotvn/</a></p>



<p>Địa chỉ Google Map:</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3933.0156589110197!2d105.56618271428006!3d9.679702581124156!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31a0e5779078d0dd%3A0xc1cc72bcc45fcf8a!2sHuynh+Hieu+Travel!5e0!3m2!1svi!2s!4v1547940847784" width="600" height="450" allowfullscreen=""></iframe></figure>
', 'Nam Du là quần thể 21 đảo lớn nhỏ. Nó nằm cách bờ thành phố Rạch Giá 65 hải lý. Diện tích đảo bao gồm 6,75km2. Dân số đảo khá nhỏ với khoảng hơn 8.000 người sinh sống. Nơi đây có đảo chỉ có 1 người sinh sống và còn được gọi là chúa đảo. [&hellip;]', 3829, 'post', '2019-01-21 11:45:12', '2023-04-23 12:43:21');
