INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (3126, 'Phú Quốc ở đâu? Thuộc tỉnh nào? Có gì? LỊCH SỬ | ĐỊA LÝ |VĂN HÓA', 'phu-quoc-o-dau', '
<p><strong>Phú Quốc</strong> là <strong>hòn đảo lớn nhất </strong>Việt Nam, năm trong <strong>vịnh Thái Lan</strong>. <strong>Năm 1671</strong> hòn đảo này được <strong>Mạc Cửu</strong> bắt đầu khai phá. Với <strong>lịch sử hơn 300 năm</strong> khai phá và biến động, Nó đang ngày càng phát triển mạnh mẽ hơn. Hãy cùng <a href="https://huynhhieutravel.com">Huynh Hieu Travel</a> tìm hiểu xem đảo Phú Quốc là gì.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/thuyết-minh-đảo-phú-quốc-2-1024x682.jpg" alt="Thuyết minh đảo Phú Quốc" class="wp-image-3740" srcset="https://media.huynhhieutravel.com/thuyết-minh-đảo-phú-quốc-2.jpg 1024w, https://media.huynhhieutravel.com/thuyết-minh-đảo-phú-quốc-2-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Thuyết minh</figcaption></figure>



<p>Tham khảo cách đi du lịch Phú Quốc với Kinh nghiệm, ăn uống, địa điểm du lịch chi tiết tại đây: <a href="https://huynhhieutravel.com/du-lich-phu-quoc" target="_blank" rel="noreferrer noopener" aria-label="https://huynhhieutravel.com/du-lich-phu-quoc (mở trong tab mới)">https://huynhhieutravel.com/du-lich-phu-quoc</a></p>



<h2 class="wp-block-heading">Địa lý</h2>



<p>Diện tích hiện tại là <strong>589,23 km2</strong> với <strong>22 hòn đảo</strong> lớn nhỏ. Dân số hiện tại hơn <strong>100.000 người</strong>. Mật độ dân số <strong>172 người/km2</strong> (Năm 2005). Đảo Phú Quốc được chia làm <strong>2 thị trấn là Dương Thới, An Đông</strong> và 8 xã khác nhau.</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow"><p>Đảo Phú Quốc nằm trong vịnh Thái Lan, phía tây nam của Việt Nam, Phú Quốc trải dài từ vĩ độ: 9°53′đến 10°28′độ vĩ bắc và kinh độ: 103°49′đến 104°05′độ kinh đông. </p><cite>Trích Wikipedia.org</cite></blockquote>



<p>Phú Quốc có địa hình <strong>chập chùng</strong> với <strong>nhiều ngọn đồi núi không quá cao</strong> nhưng cũng không quá thấp trải dài. Đất đá ở đây chủ yếu thuộc loại<strong> trầm tính</strong> nên khá<strong> thô và cứng</strong>.</p>



<p><strong>Khí hậu</strong> ở đây cũng như nhiều tỉnh miền Nam khác gồm hai mùa là <strong>mùa mưa và mùa khô</strong>. <strong>Mùa mưa </strong>kéo dài từ <strong>tháng 4, 5 đến khoảng tháng 11</strong> với thời tiết <strong>ẩm ướt</strong> và thường xuyên <strong>mưa</strong>. <strong>Mùa khô</strong> kéo dài từ <strong>cuối tháng 11 đến cuối tháng 3</strong> năm sau. Thời tiết mùa khô khá <strong>khô hạn</strong> và <strong>nắng nóng</strong> kéo dài. Đôi khi nhiệt độ đỉnh điểm lên đến <strong>35-36 độ C,</strong> hoặc thời tiết sau biến đổi khí hậu có lúc lên đến<strong> 38 độ C</strong>.</p>



<h3 class="wp-block-heading">Địa chỉ</h3>



<p>Nó nằm về phía Tây của Rạch Giá, cách đất liền hơn <strong>70km</strong>.</p>



<p><strong>Địa chỉ</strong>: TP. Phú Quốc, tỉnh Kiên Giang, Việt Nam.</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d580797.9866775674!2d103.86756801068762!3d10.156072392104818!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31a78c62b49eda17%3A0x8aa79fbbdd72cdb!2zUGjDuiBRdeG7kWM!5e0!3m2!1svi!2s!4v1547711235390" width="600" height="450" allowfullscreen=""></iframe></figure>



<h2 class="wp-block-heading">Lịch sử</h2>



<p><strong>Lịch sử Phú Quốc</strong> bắt đầu từ thời của Mạc Cửu khai phá vào <strong>năm 1671</strong>. <strong>Mạc Cửu</strong> là một người gốc Trung Hoa có tài. Tuy vậy, ông bất mãn với triều đình nhà Thanh nên quyết định dẫn theo binh lính xuôi về phương Nam lập nghiệp. </p>



<p>Sau này ông là người có công lao lớn giúp chúa Nguyễn bình đình và khai hoang các tỉnh miền Tây như Kiên Giang, Cà Mau, Bạc Liêu,&#8230; Theo sách sử đánh giá, nhờ Mạc Cửu mà lãnh thổ chúng ta kéo dài tận mũi Cà Mau mà không tốn quá nhiều xương máu, tài lực.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="583" height="325" src="https://media.huynhhieutravel.com/tàu-bè-tấp-nập-ở-phú-quốc.jpg" alt="Tàu bè tập nập ở đảo Phú Quốc" class="wp-image-3743"/><figcaption>Tàu bè tập nập</figcaption></figure>



<p>Tuy Mạc Cửu dâng các vùng lãnh thổ cho nhà Nguyễn nhưng đảo Phú Quốc vẫn thuộc lãnh thổ thường xuyên <strong>tranh chấp với người Campuchia</strong> lúc bấy giờ. Đến <strong>năm 1855</strong>, <strong>Hoàng đế Napoleon III</strong> của Pháp <strong>xác nhận Phú Quốc là lãnh thổ Việt Nam</strong>, phân chia ranh giới các tỉnh Đông Dương (Lúc bấy giờ Đông Dương đang là thuộc địa của Pháp).</p>



<p>Đến <strong>năm 1964</strong>, <strong>vua Sihanouk</strong> của Campuchia <strong>chấp nhận đường Brevie</strong> do pháp vẽ nên. Vì vậy, <strong>trên mặt pháp lý, Campuchia đã chấp nhận Phú Quốc thuộc lãnh thổ Việt Nam</strong>. Nên sau này các tranh chấp đã dần ít đi.</p>



<p>Đến <strong>năm 2014</strong>, nơi đây trở thành thành phố <strong>đô thị loại 2</strong>, và hiện đang phát triển mạnh mẽ. Nó đang vươn mình xây dựng trở thành một hòn đảo Singapore hoặc Hong Kong thứ 2. Nó có sự phát triển mạnh mẽ về du lịch, cơ sở hạ tầng và dịch vụ. Tuy vậy nó cũng đang đối mặt với nhiều thách thức về tệ nạn và môi trường xuồng cấp.</p>



<h2 class="wp-block-heading">Văn hóa Phú Quốc</h2>



<p><strong>Đảo Phú Quốc</strong> là nơi bắt nguồn của <strong>đạo Cao Đài</strong>. Hiện tại, tôn giáo chủ yếu ở đây vẫn là <strong>Phật giáo</strong>. Tuy trước đây, từ năm 1930 đã có linh mục tiến đến đây truyền đạo. Nhưng vì một số bất lợi nên sau này nhà thờ đã bị bỏ trống. Hiện đảo nơi đây chỉ có số lượng ít giáo dân (Khoảng 2.000 &#8211; 3.000).</p>



<p>Tham khảo cách đi du lịch Phú Quốc tự túc giá rẻ, lịch trình cụ thể tại đây: <a href="https://huynhhieutravel.com/du-lich-phu-quoc-tu-tuc" target="_blank" rel="noreferrer noopener" aria-label=" (mở trong tab mới)">https://huynhhieutravel.com/du-lich-phu-quoc-tu-tuc</a></p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/giới-thiệu-đảo-Phú-Quốc-1024x682.jpg" alt="Giới thiệu đảo Phú Quốc" class="wp-image-3738" srcset="https://media.huynhhieutravel.com/giới-thiệu-đảo-Phú-Quốc.jpg 1024w, https://media.huynhhieutravel.com/giới-thiệu-đảo-Phú-Quốc-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Giới thiệu</figcaption></figure>



<h2 class="wp-block-heading">Lễ hội Phú Quốc</h2>



<p>Người dân ở đây đa phần đều gắn liền với <strong>nghề biển</strong>. Vì thế, những lễ hội ở đây cũng mang âm sắc của biển khá nhiều. Sau đây là một số lễ hội lớn ở Phú Quốc.</p>



<h3 class="wp-block-heading">Lễ hội Dinh Cậu</h3>



<p><strong>Lễ hội Dinh Cậu</strong> tổ chức vào<strong> ngày 15 tháng 10 âm lịch</strong> hàng năm. Đây là lễ hội có từ lâu đời nhằm <strong>cầu một mùa biển mưa thuân gió hòa</strong>, hải sản bội thu. Bên cạnh việc tổ chức cúng viếng, lễ hội <a href="https://vi.wikipedia.org/wiki/Dinh_C%E1%BA%ADu" target="_blank" rel="noreferrer noopener" aria-label="Dinh Cậu (mở trong tab mới)">Dinh Cậu</a> còn tổ chức các <strong>trò chơi dân gian</strong>: kéo co, đua thuyền, nhảu bao bố,&#8230;</p>



<h3 class="wp-block-heading">Lễ hội Nghinh Ông Phú Quốc</h3>



<p><strong>Lễ hội Nghinh Ông</strong> ở đây được tổ chức vào <strong>rằm tháng 8 hàng năm</strong>. Ở các tỉnh miền Tây giáp biển, mỗi nơi đều có một lễ hội Nghinh Ông khác nhau. Tuy vậy, thời gian diễn ra đều khác nhau.</p>



<p>Lễ hội Nghinh Ông nhằm mục đích <strong>tôn vinh và tỏ lòng biết ơn</strong> của người dân đi biển với <strong>cá Ông</strong>. Với ngư dân, cá Ông là vị thần bảo hộ ngư dân trước những con sóng, bão lớn. Khi người dân bị đắm thuyền, cá Ông sẽ đến giúp đỡ và đưa họ vào bờ an toàn.</p>



<p>Lễ hội diễn ra với đoàn người diễu hành đêm bài vị của cá Ông ra biển. Lúc ấy, hàng trăm tàu thuyền cùng nhau đưa bài vị của Ông ra biển xa, sau đó cúng vái. Tiếp theo cùng nhau quay về, mở tiệc ăn mừng.</p>



<h3 class="wp-block-heading">Lễ hội Thủy Long Thánh Mẫu Phú Quốc</h3>



<p>Lễ hội này tổ chức vào <strong>rằm tháng giêng hàng năm</strong>. Lễ hội<strong> tôn vinh thần nữ Kim Giao</strong>, người đầu tiên khai phá hòn đảo ngọc Phú Quốc. Vì vậy, bà rất được người dân Phú Quốc kính ngưỡng. Ở đây có nhiều ngôi đền thờ của bà và nhan khói luôn nghi ngút.</p>



<p>Ngoài ra bạn cũng có thể tham khảo du lịch tỉnh Kiên Giang tại đây với các địa điểm du lịch thu hút: <a rel="noreferrer noopener" aria-label=" (mở trong tab mới)" href="https://huynhhieutravel.com/du-lich-kien-giang" target="_blank">https://huynhhieutravel.com/du-lich-kien-giang</a></p>



